33	  Stream<Either<Failure, ChatStreamEvent>> sendMessage({
34	    required String sessionId, required String content,
35	  }) {
36	    return _apiClient
37	        .sseStream('chat-messages-send', method: 'POST', pathSegments: [sessionId], body: {'content': content})
38	        .map(_mapFrame)
39	        .where((e) => e != null)
40	        .cast<Either<Failure, ChatStreamEvent>>();
41	  }
