91	class ChatRepositoryImpl implements ChatRepository {
92	  ChatRepositoryImpl(this._remoteDataSource, {required this._sessionRepository, required this._localCache});
93	
94	  final ChatRemoteDataSource _remoteDataSource;
95	  final SessionRepository _sessionRepository;
96	  final ChatLocalCache _localCache;
97	
98	  List<ChatSession> _cachedSessions = [];
99	  final Map<String, List<ChatMessage>> _cachedMessages = {};
100	  Future<void>? _localCacheLoad;
101	
102	  Future<void> _ensureLocalCacheLoaded() => _localCacheLoad ??= () async {
103	    _cachedSessions = await _localCache.readSessions();
104	    _cachedMessages.addAll(await _localCache.readAllMessages());
105	  }();
106	
107	  @override
108	  Future<Either<Failure, ChatSession>> createSession({required String title}) async {
109	    await _ensureLocalCacheLoaded();
110	    final result = await _retryAfterSilentRefreshIfExpired(
111	      () => _remoteDataSource.createSession(title: title),
112	    );
113	    return result.match(
114	      (f) => Left(f),
115	      (session) {
116	        _upsertSession(session);
117	        return Right(session);
118	      },
119	    );
120	  }
121	
122	  @override
123	  Future<Either<Failure, ChatSessionsPage>> listSessions({String? cursor, int? limit}) async {
124	    await _ensureLocalCacheLoaded();
125	    final result = await _retryAfterSilentRefreshIfExpired(
126	      () => _remoteDataSource.listSessions(cursor: cursor, limit: limit),
127	    );
128	    return result.match((f) => Left(f), (page) {
129	      for (final s in page.sessions) {
130	        _upsertSession(s);
131	      }
132	      unawaited(_localCache.writeSessions(_cachedSessions));
133	      return Right(page);
134	    });
135	  }
136	
137	  @override
138	  List<ChatSession> get cachedSessions => List.unmodifiable(_cachedSessions);
139	
140	  @override
141	  Future<Either<Failure, List<ChatMessage>>> listMessages(String sessionId) async {
142	    await _ensureLocalCacheLoaded();
143	    final result = await _retryAfterSilentRefreshIfExpired(
144	      () => _remoteDataSource.listMessages(sessionId),
145	    );
146	    return result.match((f) => Left(f), (messages) {
147	      _cachedMessages[sessionId] = messages;
148	      unawaited(_localCache.writeMessagesForSession(sessionId, messages));
149	      return Right(messages);
150	    });
151	  }
152	
153	  @override
154	  List<ChatMessage>? cachedMessages(String sessionId) => _cachedMessages[sessionId];
155	
156	  @override
157	  Future<void> setLastActiveSessionId(String? sessionId) =>
158	      _localCache.writeLastActiveSessionId(sessionId);
159	
160	  @override
161	  Future<String?> get lastActiveSessionId => _localCache.readLastActiveSessionId();
162	
163	  @override
164	  Stream<Either<Failure, ChatStreamEvent>> sendMessage({
165	    required String sessionId, required String content,
166	  }) => _streamWithAuthRetry(() => _remoteDataSource.sendMessage(sessionId: sessionId, content: content));
167	
168	  @override
169	  Stream<Either<Failure, ChatStreamEvent>> retryMessage({
170	    required String sessionId, required String userMessageId,
171	  }) => _streamWithAuthRetry(
172	    () => _remoteDataSource.retryMessage(sessionId: sessionId, userMessageId: userMessageId),
173	  );
174	
175	  /// research.md R3 — retries the whole call once only if the *first* item is AuthExpiredFailure.
176	  Stream<Either<Failure, ChatStreamEvent>> _streamWithAuthRetry(
177	    Stream<Either<Failure, ChatStreamEvent>> Function() call,
178	  ) async* {
179	    var isFirst = true;
180	    var retried = false;
181	    var stream = call();
182	    while (true) {
183	      await for (final item in stream) {
184	        if (isFirst && !retried && item.isLeft() &&
185	            item.match((f) => f is AuthExpiredFailure, (_) => false)) {
186	          final refreshed = await _sessionRepository.refresh();
187	          if (refreshed.isLeft()) {
188	            yield item;   // refresh itself failed — surface the original AuthExpiredFailure
189	            return;
190	          }
191	          retried = true;
192	          stream = call();
193	          break;   // restart the outer while(true) with the fresh stream
194	        }
195	        isFirst = false;
196	        yield item;
197	      }
198	      if (!retried || isFirst == false) return;
199	    }
200	  }
201	
202	  void _upsertSession(ChatSession session) {
203	    final i = _cachedSessions.indexWhere((s) => s.id == session.id);
204	    if (i >= 0) {
205	      _cachedSessions[i] = session;
206	    } else {
207	      _cachedSessions = [..._cachedSessions, session];
208	    }
209	  }
210	
211	  Future<Either<Failure, T>> _retryAfterSilentRefreshIfExpired<T>(
212	    Future<Either<Failure, T>> Function() call,
213	  ) async {
214	    final result = await call();
215	    return result.match(
216	      (f) => f is AuthExpiredFailure ? _retryAfterSilentRefresh(call) : Future.value(Left(f)),
217	      (v) => Future.value(Right(v)),
218	    );
219	  }
220	
221	  // _retryAfterSilentRefresh: identical to EntriesRepositoryImpl's own (exactly one retry, no loop).
222	}
223	```
